"""Runtime support for vecDSL programs generated for OpenSearch, through the official opensearch-py client. Generated by vecDSL 7. Do not edit.

Every request body (index mappings, queries, aggregations, painless and knn_score scripts with their params, temporary search
pipelines) is built by the generator and arrives here as a JSON value, identical in the Python, TypeScript and Java programs;
this module sends it with the client's transport and shapes the answer: hits become records with the key, the score in the
canonical form of vecDSL and the returned fields; weighted and relative-score hybrid search fuse their legs here (rrf is
the server's); the result-shape clauses of a hybrid search run in the shared module vecdsl_shapes over the fused records. Writes
go through the _bulk API with refresh=true, so the next statement sees them.
"""

from __future__ import annotations

import copy
import json
import math
import os
import random
import re
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence
from urllib.parse import quote

import vecdsl_shapes

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 500
_KEEP_ALIVE = "1m"
_JSON = {"accept": "application/json", "content-type": "application/json"}
_NDJSON = {"accept": "application/json", "content-type": "application/x-ndjson"}


class UnsupportedFeature(NotImplementedError):
    pass


class OpenSearchFailure(RuntimeError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

from opensearchpy import ConnectionError as TransportConnectionError, OpenSearch, TransportError  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


class Client:
    """The OpenSearch client of one program; credentials come from the environment only."""

    def __init__(self, url: str, user: str, user_variable: str | None, password_variable: str, api_key_variable: str | None,
                 timeout_seconds: float) -> None:
        if "@" in url.split("//", 1)[-1].split("/", 1)[0]:
            raise ValueError("the server URL must not contain credentials; set them in the environment")
        self.url = url
        self.timeout = timeout_seconds
        options: dict[str, Any] = {"timeout": timeout_seconds, "max_retries": 0, "retry_on_timeout": False}
        api_key = os.environ.get(api_key_variable) if api_key_variable else None
        if api_key:
            options["headers"] = {"Authorization": f"ApiKey {api_key}"}
        else:
            name = (os.environ.get(user_variable) if user_variable else None) or user
            password = os.environ.get(password_variable)
            if password is None:
                raise KeyError(f"environment variable {password_variable} is not set (the password of user {name})")
            options["http_auth"] = (name, password)
        self.os = OpenSearch(hosts=[url], **options)

    def close(self) -> None:
        self.os.close()


def connect(url: str, user: str = "admin", user_variable: str | None = "VECDSL_OPENSEARCH_USER",
            password_variable: str = "VECDSL_OPENSEARCH_PASSWORD", api_key_variable: str | None = None,
            timeout_seconds: float = 30) -> Client:
    return Client(url, user, user_variable, password_variable, api_key_variable, timeout_seconds)


class _Floats(list):
    """A float vector that keeps its decimal points in a request body (see _floats)."""


def _floats(value: Any) -> Any:
    """A float vector field's value with every element a float, nested lists (multi-vectors) included: OpenSearch's MMR
    reranker reads stored vectors from _source and casts each element to Double, so [1, 0] would fail there."""
    if isinstance(value, (list, tuple)):
        if all(isinstance(item, (int, float)) and not isinstance(item, bool) for item in value):
            return _Floats(float(item) for item in value)
        return [_floats(item) for item in value]
    return value


def _plain(value: Any) -> Any:
    """Integral floats as integers, so that request bodies read 35, not 35.0, in every host language (float vectors of
    writes excepted, see _floats)."""
    if isinstance(value, _Floats):
        return value
    if isinstance(value, float) and value.is_integer() and math.isfinite(value) and abs(value) < 1e15:
        return int(value)
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _plain(item) for key, item in value.items()}
    return value


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _send(client: Client, method: str, path: str, params: dict[str, Any] | None = None, body: Any = None,
          ignore: Sequence[int] = ()) -> Any:
    """One request. The timeout argument is always given, because the transport would otherwise take a query parameter
    named timeout (as in _cluster/health) for its own request timeout and send it nowhere."""
    query = {key: (json.dumps(value) if isinstance(value, bool) else str(_plain(value))) for key, value in (params or {}).items()}
    try:
        return client.os.transport.perform_request(method, path, params=query or None, headers=_JSON,
                                                   body=None if body is None else _plain(body), timeout=client.timeout)
    except TransportConnectionError as error:
        raise OpenSearchFailure(f"cannot reach OpenSearch at {client.url} within the request timeout: {error}") from error
    except TransportError as error:
        if error.status_code in ignore:
            return None
        raise OpenSearchFailure(f"{method} {path} failed with status {error.status_code}: {_reason(error.info)}") from error


def _send_lines(client: Client, path: str, params: dict[str, Any], lines: Sequence[Any]) -> Any:
    """An NDJSON request (the _bulk API): one JSON document per line."""
    body = "".join(json.dumps(_plain(line), separators=(",", ":")) + "\n" for line in lines)
    try:
        return client.os.transport.perform_request("POST", path, params=params, headers=_NDJSON, body=body, timeout=client.timeout)
    except TransportConnectionError as error:
        raise OpenSearchFailure(f"cannot reach OpenSearch at {client.url} within the request timeout: {error}") from error
    except TransportError as error:
        raise OpenSearchFailure(f"POST {path} failed with status {error.status_code}: {_reason(error.info)}") from error


def _reason(body: Any) -> str:
    if isinstance(body, dict) and isinstance(body.get("error"), dict):
        error = body["error"]
        cause = (error.get("root_cause") or [error])[0]
        return f"{cause.get('type')}: {cause.get('reason')}"
    return json.dumps(body)[:500]


def _select(value: Any, path: Sequence[str] | None) -> Any:
    for key in path or ():
        value = None if value is None else value.get(key)
    return value


def request(client: Client, method: str, path: str, params: dict[str, Any] | None = None, body: Any = None,
            select: Sequence[str] | None = None, wrap: str | None = None, ignore: Sequence[int] = ()) -> Any:
    """One request; select picks a member of the answer, wrap names it in a one-entry object."""
    result = _value(_select(_send(client, method, path, params, body, ignore), select))
    return {wrap: result} if wrap is not None else result


def exists(client: Client, path: str) -> bool:
    try:
        return client.os.transport.perform_request("HEAD", path, headers=_JSON, timeout=client.timeout) is True
    except TransportError as error:
        raise OpenSearchFailure(f"HEAD {path} failed with status {error.status_code}") from error


def ids(client: Client, values: Sequence[Any]) -> list[str]:
    return [_id(value) for value in values]


def _id(value: Any) -> str:
    plain = _plain(value)
    return json.dumps(plain) if isinstance(plain, bool) else str(plain)


def _similarity(score: float, form: dict[str, Any]) -> float:
    """The canonical similarity from OpenSearch's _score (k-NN SpaceType.scoreTranslation, KNNScoringSpace)."""
    kind = form["kind"]
    if kind in ("relevance", "native", "fused"):
        return score
    if kind == "cosinesimil":
        return 2 * score - 1
    if kind == "cosine_exact_byte":
        return score - 1
    if kind == "innerproduct":
        return score - 1 if score >= 1 else 1 - 1 / score
    if kind == "l2":
        return -math.sqrt(max(1 / score - 1, 0.0))
    if kind in ("l1", "linf", "hamming"):
        return -(1 / score - 1)
    raise ValueError(f"unknown score form {kind}")


def _within(score: float, bounds: dict[str, float] | None) -> bool:
    if not bounds:
        return True
    return (bounds.get("min") is None or score >= bounds["min"] - 1e-9) and (bounds.get("max") is None or score <= bounds["max"] + 1e-9)


def _record(hit: dict[str, Any], key: str, form: dict[str, Any] | None) -> dict[str, Any]:
    source = hit.get("_source") or {}
    record: dict[str, Any] = {key: source.get(key, hit.get("_id"))}
    if form is not None:
        record["score"] = _similarity(hit["_score"], form)
    for name, item in source.items():
        if name != key:
            record[name] = item
    if "highlight" in hit:
        record["highlight"] = hit["highlight"]
    if "_explanation" in hit:
        record["explanation"] = hit["_explanation"]
    return record


def _records(hits: Sequence[dict[str, Any]], key: str, form: dict[str, Any] | None, bounds: dict[str, float] | None) -> list[dict[str, Any]]:
    result = [_record(hit, key, form) for hit in hits]
    if form is not None and form["kind"] == "fused":
        result.sort(key=lambda record: _order(record, key))
    return [record for record in result if form is None or _within(record["score"], bounds)]


def _answer(client: Client, index: str, body: dict[str, Any], params: dict[str, Any] | None) -> Any:
    """A _search answer; a sliced search runs in a point in time opened for it (OpenSearch slices a point-in-time search)."""
    if "slice" not in body:
        return _send(client, "POST", f"/{index}/_search", params, body)
    pit = _send(client, "POST", f"/{index}/_search/point_in_time", {"keep_alive": _KEEP_ALIVE})["pit_id"]
    try:
        return _send(client, "POST", "/_search", params, {**body, "pit": {"id": pit, "keep_alive": _KEEP_ALIVE}})
    finally:
        _send(client, "DELETE", "/_search/point_in_time", None, {"pit_id": [pit]}, ignore=(404,))


def _after(client: Client, index: str, body: dict[str, Any], after: Any) -> list[Any] | None:
    """search_after values of a cursor: the score the search gives the cursor record, then its key; None if it does not match."""
    probe = {"query": {"bool": {"must": [body["query"]], "filter": [{"ids": {"values": [_id(after)]}}]}}, "size": 1, "_source": False}
    hits = _send(client, "POST", f"/{index}/_search", None, probe)["hits"]["hits"]
    return [hits[0]["_score"], after] if hits else None


def search(client: Client, index: str, body: dict[str, Any], key: str, score: dict[str, Any] | None = None,
           bounds: dict[str, float] | None = None, group: str | None = None, params: dict[str, Any] | None = None,
           top_k: int | None = None, after: Any = None, candidates: bool = False) -> Any:
    """A _search request; the hits as records, grouped by the collapse field, with the total and aggregations when asked;
    with candidates, the records unrounded for the shared result-shape module (see shape).

    With top_k the knn query first finds the global top k documents, and the request then runs on those documents only: a
    knn query takes k per segment, so totals, aggregations, groups, a post filter, a sort and boost functions would otherwise
    see every segment's hits. A cursor (after) continues after that record in the order of the search; a cursor the search
    does not match gives no hits.
    """
    if top_k is not None:
        body = _global_top_k(client, index, body, top_k, params)
    if after is not None:
        values = _after(client, index, body, after)
        body = {**body, "size": 0} if values is None else {**body, "search_after": values}
    answer = _answer(client, index, body, params)
    hits = answer["hits"]["hits"]
    if candidates:
        return _records(hits, key, score, bounds)
    if group is not None:
        result: Any = [{"group": hit["fields"][group][0],
                         "hits": _records(hit["inner_hits"]["group"]["hits"]["hits"], key, score, bounds)} for hit in hits]
    else:
        result = _records(hits, key, score, bounds)
    if body.get("track_total_hits") or "aggs" in body:
        shaped: dict[str, Any] = {"hits": result}
        if body.get("track_total_hits"):
            shaped["total"] = answer["hits"]["total"]["value"]
        if "aggs" in body:
            shaped["aggregations"] = answer["aggregations"]
        result = shaped
    return _value(result)


def _knn(query: dict[str, Any]) -> dict[str, Any]:
    """The knn query of a request: the query itself, or the query of the function_score query of a boost."""
    return query["function_score"]["query"] if "function_score" in query else query


def _global_top_k(client: Client, index: str, body: dict[str, Any], top_k: int, params: dict[str, Any] | None) -> dict[str, Any]:
    """The request restricted (by an ids filter in the knn query) to the global top k of its knn query."""
    first = _send(client, "POST", f"/{index}/_search", params, {"query": _knn(body["query"]), "size": top_k, "_source": False})
    ids = [hit["_id"] for hit in first["hits"]["hits"]]
    restricted = copy.deepcopy(body)
    leaf = next(iter(_knn(restricted["query"])["knn"].values()))
    only = {"ids": {"values": ids}}
    leaf["filter"] = {"bool": {"filter": [only, leaf["filter"]]}} if "filter" in leaf else only
    return restricted


def fetch(client: Client, index: str, values: Sequence[Any], key: str, fields: Sequence[str] | None = None,
          excludes: Sequence[str] | None = None, filters: Sequence[dict[str, Any]] | None = None) -> list[Any]:
    """Records by key through _mget, in the order of the keys; missing keys are skipped. Within a tenant, namespace or
    partition (filters), an ids query with the slice filter."""
    if filters:
        body: dict[str, Any] = {"query": {"bool": {"filter": [{"ids": {"values": ids(client, values)}}, *filters]}}, "size": len(values)}
        source: dict[str, Any] = {}
        if fields is not None:
            source["includes"] = [key, *fields]
        if excludes:
            source["excludes"] = list(excludes)
        if source:
            body["_source"] = source
        found = {hit["_id"]: hit for hit in _send(client, "POST", f"/{index}/_search", None, body)["hits"]["hits"]}
        return _value([_record(found[value], key, None) for value in ids(client, values) if value in found])
    params: dict[str, Any] = {}
    if fields is not None:
        params["_source_includes"] = ",".join([key, *fields])
    if excludes:
        params["_source_excludes"] = ",".join(excludes)
    answer = _send(client, "POST", f"/{index}/_mget", params, {"ids": ids(client, values)})
    return _value([_record(doc, key, None) for doc in answer["docs"] if doc.get("found")])


def _bulk(client: Client, index: str, records: Sequence[dict[str, Any]], key: str, op: str, extra: dict[str, Any] | None,
          defaults: dict[str, Any] | None, batch_size: int, vectors: Sequence[str] = ()) -> tuple[int, int]:
    written = skipped = 0
    action = "update" if op == "patch" else op
    for start in range(0, len(records), batch_size):
        lines: list[Any] = []
        for record in records[start:start + batch_size]:
            if key not in record:
                raise OpenSearchFailure(f"a record without the key {key}: {json.dumps(record)[:200]}")
            source = {**(defaults or {}), **record, **(extra or {})}
            for name in vectors:
                if source.get(name) is not None:
                    source[name] = _floats(source[name])
            lines.append({action: {"_index": index, "_id": _id(record[key])}})
            lines.append({"doc": source, "doc_as_upsert": True} if op == "update" else {"doc": source} if op == "patch" else source)
        answer = _send_lines(client, "/_bulk", {"refresh": "true"}, lines)
        for item in answer["items"]:
            outcome = item[action]
            if outcome.get("status", 500) < 300:
                written += 1
            elif (op == "create" and outcome["status"] == 409) or (op == "patch" and outcome["status"] == 404):
                skipped += 1
            else:
                raise OpenSearchFailure(f"bulk {op} of {outcome.get('_id')} failed with status {outcome.get('status')}: "
                                           f"{_reason({'error': outcome.get('error')})}")
    return written, skipped


def write(client: Client, index: str, records: Sequence[dict[str, Any]], key: str, op: str, counter: str,
          extra: dict[str, Any] | None = None, defaults: dict[str, Any] | None = None, batch_size: int = _BATCH,
          ignore_conflicts: bool = False, vectors: Sequence[str] | None = None, only: Sequence[Any] | None = None) -> dict[str, int]:
    """Records written with one _bulk request per batch: create (insert), index (replace), update (merge, created when
    missing) or patch (merge into existing documents only; a missing document is not counted); the float vector fields named
    in vectors keep their decimal points. With only, the records whose key is not among those keys are left out."""
    if only is not None:
        keys = set(ids(client, only))
        records = [record for record in records if key in record and _id(record[key]) in keys]
    written, skipped = _bulk(client, index, records, key, op, extra, defaults, batch_size, vectors or ())
    if skipped and not ignore_conflicts and op != "patch":
        raise OpenSearchFailure(f"{skipped} records of the insert into {index} already exist")
    return {counter: written, "skipped": skipped} if ignore_conflicts else {counter: written}


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, location: str, index: str, key: str, op: str, counter: str, extra: dict[str, Any] | None = None,
                defaults: dict[str, Any] | None = None, batch_size: int = _BATCH, ignore_conflicts: bool = False,
                vectors: Sequence[str] | None = None) -> dict[str, int]:
    return write(client, index, read_records(client, location), key, op, counter, extra, defaults, batch_size, ignore_conflicts,
                 vectors)


def update_if_version(client: Client, index: str, value: Any, seq_no: int, body: dict[str, Any]) -> dict[str, int]:
    """An update applied only while the document's sequence number is seq_no (optimistic concurrency control)."""
    path = f"/{index}/_doc/{quote(_id(value), safe='')}"
    current = _send(client, "GET", path, {"_source": "false"}, ignore=(404,))
    if current is None or not current.get("found"):
        return {"update_count": 0}
    params = {"if_seq_no": seq_no, "if_primary_term": current["_primary_term"], "refresh": "true"}
    updated = _send(client, "POST", f"/{index}/_update/{quote(_id(value), safe='')}", params, body, ignore=(409,))
    return {"update_count": 0 if updated is None or updated.get("result") == "noop" else 1}


def drop_matching(client: Client, pattern: str) -> None:
    """Deletes the indices a wildcard names; destructive actions take explicit names (action.destructive_requires_name)."""
    rows = _send(client, "GET", f"/_cat/indices/{pattern}", {"format": "json", "h": "index", "expand_wildcards": "all"})
    names = sorted(row["index"] for row in rows or [])
    if names:
        _send(client, "DELETE", "/" + ",".join(names))


def names(client: Client, kind: str, path: str, body: Any = None, strip: str | None = None, prefix: str | None = None,
          limit: int | None = None, ignore: Sequence[int] = ()) -> list[str]:
    """Names read from an answer: indices, database prefixes, aliases, terms of a field, vector fields or snapshots."""
    answer = _send(client, "POST" if body is not None else "GET", path, {"format": "json"} if kind in ("indices", "databases") else None,
                   body, ignore)
    found: list[str] = []
    if answer is None:
        found = []
    elif kind == "indices":
        found = [row["index"] for row in answer]
    elif kind == "databases":
        found = [row["index"].split(".", 1)[0] for row in answer if "." in row["index"].lstrip(".")]
    elif kind == "aliases":
        found = [alias for entry in answer.values() for alias in entry.get("aliases", {})]
    elif kind == "terms":
        found = [str(bucket["key"]) for bucket in answer["aggregations"]["names"]["buckets"]]
    elif kind == "vector_fields":
        found = [name for entry in answer.values() for name, field in entry["mappings"].get("properties", {}).items()
                 if field.get("type") in ("knn_vector", "rank_features")]
    elif kind == "snapshots":
        found = [snapshot["snapshot"] for snapshot in answer.get("snapshots", [])]
    found = sorted({name[len(strip):] if strip and name.startswith(strip) else name for name in found if not name.startswith(".")})
    if prefix is not None:
        found = [name for name in found if name.startswith(prefix)]
    return found[:limit] if limit is not None else found


def wait_health(client: Client, index: str, status: str, timeout_seconds: int) -> str:
    """The health of an index once it reaches status, or a clear error after timeout_seconds."""
    answer = _send(client, "GET", f"/_cluster/health/{index}", {"wait_for_status": status, "timeout": f"{timeout_seconds}s"},
                   ignore=(408,))
    if answer is None or answer.get("timed_out"):
        raise TimeoutError(f"index {index} did not reach health {status} within {timeout_seconds} seconds")
    return answer["status"]


def _vectors(client: Client, index: str, field: str, values: Sequence[Any]) -> list[list[float]]:
    if not values:
        return []
    answer = _send(client, "POST", f"/{index}/_mget", {"_source_includes": field}, {"ids": ids(client, values)})
    found = [doc["_source"][field] for doc in answer["docs"] if doc.get("found") and field in doc.get("_source", {})]
    if len(found) != len(values):
        raise OpenSearchFailure(f"an example of the recommendation has no {field} vector in {index}")
    return found


def _average(vectors: Sequence[Sequence[float]]) -> list[float]:
    return [sum(column) / len(vectors) for column in zip(*vectors)]


def _with_vector(body: dict[str, Any], field: str, vector: list[float]) -> dict[str, Any]:
    """The search body with the computed query vector in its knn query (also inside the function_score query of a boost) or
    in the params of its knn_score script."""
    filled = copy.deepcopy(body)
    query = _knn(filled["query"])
    if "knn" in query:
        query["knn"][field]["vector"] = vector
    else:
        query["script_score"]["script"]["params"]["query_value"] = vector
    return filled


def recommend(client: Client, index: str, lookup: str, field: str, key: str, body: dict[str, Any], score: dict[str, Any],
              positive_ids: Sequence[Any] = (), positive_vectors: Sequence[Sequence[float]] = (), negative_ids: Sequence[Any] = (),
              negative_vectors: Sequence[Sequence[float]] = (), bounds: dict[str, float] | None = None, group: str | None = None,
              top_k: int | None = None, after: Any = None) -> Any:
    """Qdrant's average-vector strategy: avg(positive) + (avg(positive) - avg(negative)) as the query vector."""
    positives = [*_vectors(client, lookup, field, positive_ids), *positive_vectors]
    negatives = [*_vectors(client, lookup, field, negative_ids), *negative_vectors]
    query = _average(positives)
    if negatives:
        avoid = _average(negatives)
        query = [2 * p - n for p, n in zip(query, avoid)]
    return search(client, index, _with_vector(body, field, query), key, score, bounds, group, None, top_k, after)


def _order(record: dict[str, Any], key: str) -> tuple[Any, ...]:
    value = record[key]
    return (-record["score"], 0, value, "") if isinstance(value, (int, float)) else (-record["score"], 1, 0, str(value))


def hybrid(client: Client, index: str, legs: Sequence[dict[str, Any]], fusion: str, k: int, size: int, offset: int, key: str,
           bounds: dict[str, float] | None = None, candidates: bool = False) -> list[Any]:
    """Fusion of the legs' hits: rrf sums 1/(k + rank), weighted sums weight * similarity, relative_score sums the
    weighted min-max normalized similarities; ties by key. A fused record carries the first highlight of its legs and one
    explanation per leg (null where the leg did not return the record). With candidates, the fused records come back
    unrounded for the shared result-shape module (see shape)."""
    fused: dict[str, dict[str, Any]] = {}
    for position, leg in enumerate(legs):
        hits = [_record(hit, key, leg["score"]) for hit in _send(client, "POST", f"/{index}/_search", None, leg["body"])["hits"]["hits"]]
        scores = [hit["score"] for hit in hits]
        low, high = (min(scores), max(scores)) if scores else (0.0, 0.0)
        for rank, hit in enumerate(hits, start=1):
            if fusion == "rrf":
                part = 1 / (k + rank)
            elif fusion == "relative_score":
                part = leg["weight"] * ((hit["score"] - low) / (high - low) if high > low else 1.0)
            else:
                part = leg["weight"] * hit["score"]
            entry = fused.setdefault(_id(hit[key]), {**{name: value for name, value in hit.items()
                                                       if name not in ("score", "highlight", "explanation")}, "score": 0.0})
            entry["score"] += part
            if "highlight" in hit:
                entry.setdefault("highlight", hit["highlight"])
            if "explanation" in hit:
                entry.setdefault("explanation", [None] * len(legs))[position] = hit["explanation"]
    ranked = sorted((record for record in fused.values() if _within(record["score"], bounds)), key=lambda record: _order(record, key))
    page = ranked[offset:offset + size]
    return page if candidates else _value(page)


def shape(client: Client, candidates: Sequence[dict[str, Any]], spec: dict[str, Any], vectors: Sequence[str]) -> Any:
    """The result-shape clauses over a candidate window, by the shared module vecdsl_shapes: each record becomes a candidate
    {key, score, fields, vectors, highlight, explanation}; the vector fields the candidates carry go to vectors and stay among
    the fields only where the output names them."""
    key = spec["keyField"]
    listed = set(spec.get("output") or ())
    items = []
    for record in candidates:
        item: dict[str, Any] = {
            "key": record[key], "score": record.get("score"),
            "fields": {name: value for name, value in record.items()
                       if name not in (key, "score", "highlight", "explanation") and (name not in vectors or name in listed)},
            "vectors": {name: record[name] for name in vectors if name in record}}
        for name in ("highlight", "explanation"):
            if name in record:
                item[name] = record[name]
        items.append(item)
    try:
        return vecdsl_shapes.shape(items, spec)
    except vecdsl_shapes.UnsupportedShape as error:
        unsupported("opensearch", str(error))


def distance_matrix(client: Client, index: str, field: str, key: str, sample: int, limit: int, score: dict[str, Any],
                    query: dict[str, Any]) -> list[Any]:
    """Qdrant's definition: a random sample of the matching documents, each with its nearest neighbours in the sample."""
    body = {"size": sample, "_source": {"includes": [key, field]},
            "query": {"function_score": {"query": query, "random_score": {"seed": random.randrange(1 << 30), "field": "_seq_no"}}}}
    docs = _send(client, "POST", f"/{index}/_search", None, body)["hits"]["hits"]
    members = [doc["_id"] for doc in docs]
    result = []
    for doc in docs:
        others = [member for member in members if member != doc["_id"]]
        knn = {"knn": {field: {"vector": doc["_source"][field], "k": max(1, min(limit, len(others))), "filter": {"ids": {"values": others}}}}}
        hits = _send(client, "POST", f"/{index}/_search", None, {"size": limit, "query": knn, "_source": [key]})["hits"]["hits"] if others else []
        result.append({"id": doc["_source"].get(key, doc["_id"]),
                       "neighbours": [{"id": hit["_source"].get(key, hit["_id"]), "score": _similarity(hit["_score"], score)} for hit in hits]})
    return _value(result)
